import re,subprocess
seen=set()
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    for c in subprocess.run(['git','rev-list',f'origin/friend/{b}'],capture_output=True,text=True).stdout.split():
        body=subprocess.run(['git','log','-1','--format=%B',c],capture_output=True,text=True).stdout
        if 'Friend-Message: 1' in body and 'S02/E13' in body:
            ts=subprocess.run(['git','log','-1','--format=%cI',c],capture_output=True,text=True).stdout.strip()
            seen.add((ts,c,b))
for x in sorted(seen)[-4:]: print(x)
